lue="<?=$x['id']?>"><?=htmlspecialchars($x['codigo'].' · '.$x['nombre'])?></option><?php endforeach;?></select></label><label>Debe haber aprobado<select name="prerrequisito_id" required><option value="">Seleccione</option><?php foreach($items as $x):?><option value="<?=$x['id']?>"><?=htmlspecialchars($x['codigo'].' · '.$x['nombre'])?></option><?php endforeach;?></select></label><div><button class="btn">Agregar prerrequisito</button></div></form></section><?php endif;?><?php endif;?>
